-- Sales: clients, website quote requests, versioned quotations and invoices.
begin;

do $guard$
begin
  if exists (select 1 from information_schema.tables where table_schema='invoicing' and table_name='invoices') then raise exception 'Sales already exists. Refusing to replace it.'; end if;
end $guard$;

create type invoicing.invoice_status as enum ('draft','sent','paid','cancelled');
create type quoting.request_status as enum ('new','reviewing','quoted','accepted','declined','closed');
create type quoting.quote_status as enum ('draft','issued','accepted','declined','expired','discarded');

create table invoicing.clients (
 id uuid primary key default gen_random_uuid(), organisation_name text not null check(btrim(organisation_name)<>'' and char_length(organisation_name)<=200), contact_name text check(char_length(contact_name)<=120), address_line1 text not null check(btrim(address_line1)<>'' and char_length(address_line1)<=200), address_line2 text check(char_length(address_line2)<=200), city text not null check(btrim(city)<>'' and char_length(city)<=100), postcode text not null check(btrim(postcode)<>'' and char_length(postcode)<=16), country text not null default 'United Kingdom' check(char_length(country)<=100), email text not null check(char_length(email)<=254 and email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]{2,}$'), phone text check(char_length(phone)<=40), notes text check(char_length(notes)<=2000), archived boolean not null default false, created_by uuid not null references emblara.staff(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table invoicing.invoice_counter (id smallint primary key default 1 check(id=1), last_number integer not null default 0 check(last_number>=0)); insert into invoicing.invoice_counter(id) values(1);
create table invoicing.invoices (
 id uuid primary key default gen_random_uuid(), number text not null unique check(number ~ '^EMB-[0-9]{4,}$'), client_id uuid not null references invoicing.clients(id), status invoicing.invoice_status not null default 'draft', issue_date date not null default (now() at time zone 'Europe/London')::date, due_date date not null, deposit_percent numeric(5,2) not null default 100 check(deposit_percent>0 and deposit_percent<=100), delivery_estimate text check(char_length(delivery_estimate)<=1000), artwork_note text check(char_length(artwork_note)<=1000), returns_note text check(char_length(returns_note)<=1000), notes text check(char_length(notes)<=2000), subtotal_pence bigint not null default 0 check(subtotal_pence>=0), total_pence bigint not null default 0 check(total_pence>=0), deposit_due_pence bigint not null default 0 check(deposit_due_pence>=0), balance_due_pence bigint not null default 0 check(balance_due_pence>=0), sent_at timestamptz, paid_at timestamptz, cancelled_at timestamptz, cancel_reason text check(char_length(cancel_reason)<=500), created_by uuid not null references emblara.staff(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint due_after_issue check(due_date>=issue_date), constraint invoice_totals check(total_pence=deposit_due_pence+balance_due_pence));
create table invoicing.invoice_lines (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references invoicing.invoices(id), line_no integer not null check(line_no>0), description text not null check(btrim(description)<>'' and char_length(description)<=500), quantity integer not null check(quantity>0), unit_price_pence bigint not null check(unit_price_pence>=0), line_total_pence bigint generated always as (quantity::bigint*unit_price_pence) stored, unique(invoice_id,line_no));
create table invoicing.invoice_events (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references invoicing.invoices(id), event_type text not null check(event_type in ('created','sent','paid','payment_undone','cancelled','reopened')), detail text check(char_length(detail)<=500), created_by uuid not null references emblara.staff(id), created_at timestamptz not null default now());
create table invoicing.invoice_documents (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references invoicing.invoices(id), pdf bytea not null check(octet_length(pdf)>0 and octet_length(pdf)<=10485760), created_by uuid not null references emblara.staff(id), created_at timestamptz not null default now());

create table quoting.counters (id smallint primary key default 1 check(id=1), last_request integer not null default 0, last_quote integer not null default 0); insert into quoting.counters(id) values(1);
create table quoting.quote_requests (id uuid primary key default gen_random_uuid(), reference text not null unique check(reference ~ '^QR-[0-9]{4,}$'), submission_key uuid not null unique, status quoting.request_status not null default 'new', contact_name text not null check(btrim(contact_name)<>'' and char_length(contact_name)<=120), organisation text not null check(btrim(organisation)<>'' and char_length(organisation)<=200), email text not null check(char_length(email)<=254 and email=lower(email)), phone text check(char_length(phone)<=40), garments text[] not null check(cardinality(garments) between 1 and 4), decoration text not null check(decoration in ('print','embroidery','not_sure')), colours text not null check(char_length(colours)<=300), quantity_total integer check(quantity_total between 1 and 100000), quantity_unsure boolean not null default false, needed_by date not null, purpose text not null check(purpose in ('staff_uniform','club_kit','event','other')), delivery_postcode text not null check(char_length(delivery_postcode)<=16), single_address boolean not null, notes text check(char_length(notes)<=2000), consent_at timestamptz not null, privacy_notice_version text not null check(char_length(privacy_notice_version)<=40), staff_notes text check(char_length(staff_notes)<=4000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint request_quantity check((quantity_unsure and quantity_total is null) or (not quantity_unsure and quantity_total is not null)));
create table quoting.quotes (id uuid primary key default gen_random_uuid(), request_id uuid not null references quoting.quote_requests(id), version integer not null default 1 check(version>0), quote_number text unique check(quote_number is null or quote_number ~ '^EMB-Q-[0-9]{4,}$'), status quoting.quote_status not null default 'draft', valid_until date, deposit_percent numeric(5,2) not null default 100 check(deposit_percent>0 and deposit_percent<=100), timeline_text text check(char_length(timeline_text)<=1000), artwork_note text check(char_length(artwork_note)<=1000), returns_note text check(char_length(returns_note)<=1000), customer_notes text check(char_length(customer_notes)<=2000), total_pence bigint not null default 0 check(total_pence>=0), token_hash bytea unique, issued_at timestamptz, decided_at timestamptz, customer_message text check(char_length(customer_message)<=2000), created_by uuid not null references emblara.staff(id), created_at timestamptz not null default now(), unique(request_id,version));
create table quoting.quote_lines (id uuid primary key default gen_random_uuid(), quote_id uuid not null references quoting.quotes(id), line_no integer not null check(line_no>0), description text not null check(btrim(description)<>'' and char_length(description)<=500), quantity integer not null check(quantity>0), unit_price_pence bigint not null check(unit_price_pence>=0), line_total_pence bigint generated always as(quantity::bigint*unit_price_pence) stored, unique(quote_id,line_no));

create function invoicing.recalculate_invoice(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin update invoicing.invoices set subtotal_pence=coalesce((select sum(line_total_pence) from invoicing.invoice_lines where invoice_id=p_id),0), total_pence=coalesce((select sum(line_total_pence) from invoicing.invoice_lines where invoice_id=p_id),0), deposit_due_pence=round(coalesce((select sum(line_total_pence) from invoicing.invoice_lines where invoice_id=p_id),0)*deposit_percent/100), balance_due_pence=coalesce((select sum(line_total_pence) from invoicing.invoice_lines where invoice_id=p_id),0)-round(coalesce((select sum(line_total_pence) from invoicing.invoice_lines where invoice_id=p_id),0)*deposit_percent/100), updated_at=now() where id=p_id; end $$;
create function invoicing.create_client(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid; begin if not emblara.is_staff() or jsonb_typeof(p) <> 'object' then raise exception 'not_staff' using errcode='42501'; end if; insert into invoicing.clients(organisation_name,contact_name,address_line1,address_line2,city,postcode,country,email,phone,notes,created_by) values(btrim(p->>'organisation_name'),nullif(btrim(p->>'contact_name'),''),btrim(p->>'address_line1'),nullif(btrim(p->>'address_line2'),''),btrim(p->>'city'),btrim(p->>'postcode'),coalesce(nullif(btrim(p->>'country'),''),'United Kingdom'),lower(btrim(p->>'email')),nullif(btrim(p->>'phone'),''),nullif(btrim(p->>'notes'),''),emblara.acting_staff_id()) returning id into v; return v; exception when check_violation or not_null_violation then raise exception 'client_invalid' using errcode='22023'; end $$;
create function invoicing.create_invoice(p_client uuid, p_deposit numeric default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_num integer; v_terms integer; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; if not exists(select 1 from invoicing.clients where id=p_client and not archived) then raise exception 'client_not_found'; end if; update invoicing.invoice_counter set last_number=last_number+1 where id=1 returning last_number into v_num; select default_payment_terms_days into v_terms from invoicing.business_profile where id=1; insert into invoicing.invoices(number,client_id,due_date,deposit_percent,delivery_estimate,artwork_note,returns_note,created_by) select 'EMB-'||lpad(v_num::text,4,'0'),p_client,((now() at time zone 'Europe/London')::date+v_terms),coalesce(p_deposit,default_deposit_percent),default_delivery_estimate,default_artwork_note,default_returns_note,emblara.acting_staff_id() from invoicing.business_profile where id=1 returning id into v_id; insert into invoicing.invoice_events(invoice_id,event_type,created_by) values(v_id,'created',emblara.acting_staff_id()); return v_id; end $$;
create function quoting.submit_request(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_num integer; v_ref text; v_key uuid; begin if jsonb_typeof(p)<>'object' then raise exception 'request_invalid'; end if; v_key:=(p->>'submission_key')::uuid; select id,reference into v_id,v_ref from quoting.quote_requests where submission_key=v_key; if found then return jsonb_build_object('id',v_id,'reference',v_ref); end if; update quoting.counters set last_request=last_request+1 where id=1 returning last_request into v_num; insert into quoting.quote_requests(reference,submission_key,contact_name,organisation,email,phone,garments,decoration,colours,quantity_total,quantity_unsure,needed_by,purpose,delivery_postcode,single_address,notes,consent_at,privacy_notice_version) values('QR-'||lpad(v_num::text,4,'0'),v_key,btrim(p->>'contact_name'),btrim(p->>'organisation'),lower(btrim(p->>'email')),nullif(btrim(p->>'phone'),''),array(select jsonb_array_elements_text(p->'garments')),p->>'decoration',btrim(p->>'colours'),nullif(p->>'quantity_total','')::integer,coalesce((p->>'quantity_unsure')::boolean,false),(p->>'needed_by')::date,p->>'purpose',upper(btrim(p->>'delivery_postcode')),coalesce((p->>'single_address')::boolean,false),nullif(btrim(p->>'notes'),''),now(),btrim(p->>'privacy_notice_version')) returning id,reference into v_id,v_ref; return jsonb_build_object('id',v_id,'reference',v_ref); exception when others then raise exception 'request_invalid' using errcode='22023'; end $$;
create function quoting.get_quote_by_token(p_token text) returns jsonb language sql security definer set search_path='' as $$ select jsonb_build_object('number',q.quote_number,'status',q.status,'valid_until',q.valid_until,'deposit_percent',q.deposit_percent,'timeline_text',q.timeline_text,'artwork_note',q.artwork_note,'returns_note',q.returns_note,'customer_notes',q.customer_notes,'total_pence',q.total_pence,'lines',coalesce((select jsonb_agg(jsonb_build_object('description',l.description,'quantity',l.quantity,'unit_price_pence',l.unit_price_pence,'line_total_pence',l.line_total_pence) order by l.line_no) from quoting.quote_lines l where l.quote_id=q.id),'[]'::jsonb)) from quoting.quotes q where q.status='issued' and q.valid_until >= (now() at time zone 'Europe/London')::date and q.token_hash=public.digest(p_token::bytea,'sha256') $$;
create function quoting.respond_to_quote(p_token text,p_decision text,p_message text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v quoting.quotes; begin select * into v from quoting.quotes where token_hash=public.digest(p_token::bytea,'sha256') for update; if not found or v.status<>'issued' or v.valid_until<(now() at time zone 'Europe/London')::date or p_decision not in ('accepted','declined') then raise exception 'quote_not_available' using errcode='P0002'; end if; update quoting.quotes set status=p_decision::quoting.quote_status, decided_at=now(), customer_message=nullif(btrim(p_message),'') where id=v.id; update quoting.quote_requests set status=p_decision::quoting.request_status where id=v.request_id; return jsonb_build_object('status',p_decision); end $$;

alter table quoting.quotes add column token_ciphertext text check(char_length(token_ciphertext)<=1000);
create function invoicing.add_invoice_line(p_invoice uuid,p_description text,p_quantity integer,p_unit_pence bigint) returns void language plpgsql security definer set search_path='' as $$ declare v_line integer; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; if not exists(select 1 from invoicing.invoices where id=p_invoice and status='draft') then raise exception 'invoice_not_draft'; end if; select coalesce(max(line_no),0)+1 into v_line from invoicing.invoice_lines where invoice_id=p_invoice; insert into invoicing.invoice_lines(invoice_id,line_no,description,quantity,unit_price_pence) values(p_invoice,v_line,btrim(p_description),p_quantity,p_unit_pence); perform invoicing.recalculate_invoice(p_invoice); end $$;
create function invoicing.invoice_transition(p_invoice uuid,p_to invoicing.invoice_status,p_reason text default null) returns invoicing.invoices language plpgsql security definer set search_path='' as $$ declare v invoicing.invoices; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; select * into v from invoicing.invoices where id=p_invoice for update; if not found then raise exception 'invoice_not_found'; end if; if (v.status,p_to) not in (('draft','sent'),('sent','paid'),('sent','draft'),('draft','cancelled'),('sent','cancelled')) then raise exception 'invoice_transition_not_allowed'; end if; if p_to in ('cancelled','draft') and nullif(btrim(p_reason),'') is null then raise exception 'reason_required'; end if; update invoicing.invoices set status=p_to,sent_at=case when p_to='sent' then now() else sent_at end,paid_at=case when p_to='paid' then now() else null end,cancelled_at=case when p_to='cancelled' then now() else null end,cancel_reason=case when p_to='cancelled' then btrim(p_reason) else null end,updated_at=now() where id=p_invoice returning * into v; insert into invoicing.invoice_events(invoice_id,event_type,detail,created_by) values(p_invoice,case when p_to='draft' then 'reopened' else p_to::text end,case when p_to='draft' then btrim(p_reason) end,emblara.acting_staff_id()); return v; end $$;
create function invoicing.store_invoice_pdf(p_invoice uuid,p_pdf bytea) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not emblara.is_staff() or p_pdf is null or octet_length(p_pdf) not between 1 and 10485760 then raise exception 'invoice_pdf_invalid'; end if; if not exists(select 1 from invoicing.invoices where id=p_invoice) then raise exception 'invoice_not_found'; end if; insert into invoicing.invoice_documents(invoice_id,pdf,created_by) values(p_invoice,p_pdf,emblara.acting_staff_id()) returning id into v_id; return v_id; end $$;
create function quoting.create_quote(p_request uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_version integer; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; if not exists(select 1 from quoting.quote_requests where id=p_request and status in ('new','reviewing','quoted')) then raise exception 'request_not_available'; end if; select coalesce(max(version),0)+1 into v_version from quoting.quotes where request_id=p_request; insert into quoting.quotes(request_id,version,deposit_percent,timeline_text,artwork_note,returns_note,created_by) select p_request,v_version,default_deposit_percent,default_delivery_estimate,default_artwork_note,default_returns_note,emblara.acting_staff_id() from invoicing.business_profile where id=1 returning id into v_id; return v_id; end $$;
create function quoting.add_quote_line(p_quote uuid,p_description text,p_quantity integer,p_unit_pence bigint) returns void language plpgsql security definer set search_path='' as $$ declare v_line integer; begin if not emblara.is_staff() then raise exception 'not_staff' using errcode='42501'; end if; if not exists(select 1 from quoting.quotes where id=p_quote and status='draft') then raise exception 'quote_not_draft'; end if; select coalesce(max(line_no),0)+1 into v_line from quoting.quote_lines where quote_id=p_quote; insert into quoting.quote_lines(quote_id,line_no,description,quantity,unit_price_pence) values(p_quote,v_line,btrim(p_description),p_quantity,p_unit_pence); update quoting.quotes set total_pence=coalesce((select sum(line_total_pence) from quoting.quote_lines where quote_id=p_quote),0) where id=p_quote; end $$;
create function quoting.issue_quote(p_quote uuid,p_token text,p_ciphertext text) returns quoting.quotes language plpgsql security definer set search_path='' as $$ declare v quoting.quotes; v_num integer; begin if not emblara.is_staff() or char_length(p_token) not between 32 and 200 or nullif(btrim(p_ciphertext),'') is null then raise exception 'quote_invalid'; end if; select * into v from quoting.quotes where id=p_quote for update; if not found or v.status<>'draft' or v.total_pence<=0 or not exists(select 1 from quoting.quote_lines where quote_id=p_quote) then raise exception 'quote_not_ready'; end if; update quoting.counters set last_quote=last_quote+1 where id=1 returning last_quote into v_num; update quoting.quotes set quote_number='EMB-Q-'||lpad(v_num::text,4,'0'),status='issued',valid_until=(now() at time zone 'Europe/London')::date+14,token_hash=public.digest(p_token::bytea,'sha256'),token_ciphertext=p_ciphertext,issued_at=now() where id=p_quote returning * into v; update quoting.quote_requests set status='quoted' where id=v.request_id; return v; end $$;

alter table invoicing.clients enable row level security; alter table invoicing.invoices enable row level security; alter table invoicing.invoice_lines enable row level security; alter table invoicing.invoice_events enable row level security; alter table invoicing.invoice_documents enable row level security; alter table quoting.quote_requests enable row level security; alter table quoting.quotes enable row level security; alter table quoting.quote_lines enable row level security;
grant select on invoicing.clients,invoicing.invoices,invoicing.invoice_lines,invoicing.invoice_events,invoicing.invoice_documents,quoting.quote_requests,quoting.quotes,quoting.quote_lines to emblara_app;
create policy clients_read on invoicing.clients for select to emblara_app using(emblara.is_staff()); create policy invoices_read on invoicing.invoices for select to emblara_app using(emblara.is_staff()); create policy invoice_lines_read on invoicing.invoice_lines for select to emblara_app using(emblara.is_staff()); create policy invoice_events_read on invoicing.invoice_events for select to emblara_app using(emblara.is_staff()); create policy invoice_docs_read on invoicing.invoice_documents for select to emblara_app using(emblara.is_staff()); create policy requests_read on quoting.quote_requests for select to emblara_app using(emblara.is_staff()); create policy quotes_read on quoting.quotes for select to emblara_app using(emblara.is_staff()); create policy quote_lines_read on quoting.quote_lines for select to emblara_app using(emblara.is_staff());
revoke all on function invoicing.create_client(jsonb),invoicing.create_invoice(uuid,numeric),invoicing.add_invoice_line(uuid,text,integer,bigint),invoicing.invoice_transition(uuid,invoicing.invoice_status,text),invoicing.store_invoice_pdf(uuid,bytea),quoting.create_quote(uuid),quoting.add_quote_line(uuid,text,integer,bigint),quoting.issue_quote(uuid,text,text),quoting.submit_request(jsonb),quoting.get_quote_by_token(text),quoting.respond_to_quote(text,text,text) from public; grant execute on function invoicing.create_client(jsonb),invoicing.create_invoice(uuid,numeric),invoicing.add_invoice_line(uuid,text,integer,bigint),invoicing.invoice_transition(uuid,invoicing.invoice_status,text),invoicing.store_invoice_pdf(uuid,bytea),quoting.create_quote(uuid),quoting.add_quote_line(uuid,text,integer,bigint),quoting.issue_quote(uuid,text,text) to emblara_app; grant usage on schema quoting to emblara_portal; grant execute on function quoting.submit_request(jsonb),quoting.get_quote_by_token(text),quoting.respond_to_quote(text,text,text) to emblara_portal;
commit;
